cat > src/types/events.ts <<'EOF'
/**
 * Normalized event model.
 *
 * Two invariants:
 *  1. Raw evidence is never discarded. Every normalized event carries the
 *     provider's original record verbatim, plus a reference to where it came
 *     from, so higher-level state can always be traced back.
 *  2. Failing to classify an event is not a reason to drop it. Unrecognized
 *     records become `unknown` and are stored like any other.
 */

export type NormalizedEventKind =
  | 'session_started'
  | 'agent_message'
  | 'user_instruction'
  | 'tool_started'
  | 'tool_finished'
  | 'command_started'
  | 'command_finished'
  | 'file_changed'
  | 'test_started'
  | 'test_finished'
  | 'permission_requested'
  | 'session_waiting'
  | 'session_finished'
  | 'unknown';

/** Where the raw record physically lives, so it can be re-read on demand. */
export interface RawEventRef {
  /** Provider-specific source, e.g. a transcript file path. */
  source: string;
  byteOffset: number;
  line: number;
}

export interface NormalizedEvent {
  id: string;
  /** Vowe session id (`${provider}:${providerSessionId}`). */
  sessionId: string;
  /** Monotonic per-session ordering. */
  seq: number;
  at: string;
  kind: NormalizedEventKind;
  /** Deterministic one-line description. No LLM involved. */
  summary: string;
  detail?: Record<string, unknown>;
  /** The provider's record, verbatim. */
  raw: unknown;
  rawRef: RawEventRef;
}

/** Everything an adapter knows about an event except its Vowe-side identity. */
export type AdapterEvent = Omit<NormalizedEvent, 'id' | 'seq'>;
EOF
cat > src/types/conversation.ts <<'EOF'
/**
 * The companion conversation attached to a session.
 *
 * `user_question` / `companion_answer` never reach the worker.
 * `user_instruction` / `instruction_result` always do.
 * The role is what records which side of that boundary an entry crossed.
 */
export type ConversationRole =
  | 'user_question'
  | 'companion_answer'
  | 'user_instruction'
  | 'instruction_result'
  | 'system_note';

export interface ConversationEntry {
  id: string;
  sessionId: string;
  at: string;
  role: ConversationRole;
  text: string;
  provenance?: {
    eventIds: string[];
    semanticUpdatedAt?: string;
  };
}

/** True for the roles that were delivered to the underlying worker. */
export function reachedWorker(role: ConversationRole): boolean {
  return role === 'user_instruction' || role === 'instruction_result';
}
EOF
cat > src/types/errors.ts <<'EOF'
/** Thrown when a session cannot currently support a requested operation. */
export class CapabilityUnsupportedError extends Error {
  readonly sessionId: string;
  readonly capability: string;
  readonly reason: string;

  constructor(sessionId: string, capability: string, reason: string) {
    super(`Session ${sessionId} does not support ${capability}: ${reason}`);
    this.name = 'CapabilityUnsupportedError';
    this.sessionId = sessionId;
    this.capability = capability;
    this.reason = reason;
  }
}

/** Thrown when an operation names a session we have never seen. */
export class UnknownSessionError extends Error {
  constructor(sessionId: string) {
    super(`Unknown session: ${sessionId}`);
    this.name = 'UnknownSessionError';
  }
}
EOF
cat > src/types/adapter.ts <<'EOF'
import type { AdapterEvent } from './events.js';
import type { AgentSession } from './session.js';

export type Unsubscribe = () => void;

export interface InstructionResult {
  delivered: boolean;
  /** How the instruction reached the worker, for the audit trail. */
  via: string;
  /** Present when the provider echoes an id for the delivered instruction. */
  providerMessageId?: string;
  note?: string;
}

export interface LaunchOptions {
  cwd: string;
  prompt: string;
}

/**
 * The boundary between Vowe and one coding-agent provider.
 *
 * Everything provider-specific — identifiers, transport, event shapes, file
 * layouts — stays behind this interface. The rest of the application only ever
 * sees normalized sessions and normalized events.
 *
 * Providers differ in what they can do, so an adapter reports capabilities per
 * session rather than promising every operation. Optional methods may be
 * absent entirely; present methods must still throw
 * `CapabilityUnsupportedError` when a particular session cannot support them.
 */
export interface AgentAdapter {
  readonly provider: string;

  /** Current best view of every session this adapter can see. */
  discoverSessions(): Promise<AgentSession[]>;

  getSession(providerSessionId: string): Promise<AgentSession | null>;

  /**
   * Stream observable activity. Implementations should replay from
   * `fromRawRefSource`-independent internal offsets so no event is lost across
   * restarts; ordering must be stable.
   */
  subscribeToEvents(
    providerSessionId: string,
    onEvent: (event: AdapterEvent) => void,
  ): Unsubscribe;

  /** Deliver an instruction to the actual worker. */
  sendInstruction(
    providerSessionId: string,
    text: string,
  ): Promise<InstructionResult>;

  /** Optional: providers that can start new work on our behalf. */
  launchSession?(options: LaunchOptions): Promise<AgentSession>;

  /** Optional: providers that can interrupt work in progress. */
  interrupt?(providerSessionId: string): Promise<void>;

  /** Release watchers, subprocesses and handles. */
  dispose?(): Promise<void>;
}
EOF
cat > src/types/index.ts <<'EOF'
export * from './session.js';
export * from './events.js';
export * from './conversation.js';
export * from './adapter.js';
export * from './errors.js';
EOF
echo ok

