import json,glob,collections
files = sorted(glob.glob('/Users/dev/.claude/projects/*/*.jsonl'))
print(len(files),"transcripts")
shapes=collections.Counter()
samples={}
for f in files[:40]:
    for line in open(f, errors='replace'):
        try: d=json.loads(line)
        except: continue
        t=d.get('type')
        if t=='assistant':
            for b in (d.get('message') or {}).get('content') or []:
                k=('assistant',b.get('type'), b.get('name') if b.get('type')=='tool_use' else None)
                shapes[k]+=1; samples.setdefault(k,(f,d))
        elif t=='user':
            msg=d.get('message') or {}
            c=msg.get('content')
            if isinstance(c,list):
                for b in c:
                    k=('user',b.get('type'),'toolUseResult' if 'toolUseResult' in d else None)
                    shapes[k]+=1; samples.setdefault(k,(f,d))
            else:
                k=('user','text',None); shapes[k]+=1; samples.setdefault(k,(f,d))
        else:
            k=(t,d.get('subtype'),None); shapes[k]+=1; samples.setdefault(k,(f,d))
for k,v in shapes.most_common(30): print(v,k)
PY

